css:
:root {
  /* ── XL tier: backgrounds (S ≤ 0.08) ── */
  --page-bg: #f5f5f4;
  --section-bg: #f2f1f0;
  /* ── L tier: surfaces (S ≤ 0.15) ── */
  --card-bg: #ebeae8;
  --table-stripe: #ededeb;
  /* ── M tier: structural fills (S ≤ 0.30) ── */
  --header-fill: #4e4732;
  --cover-block: #746c56;
  /* ── S tier: edges & icons (S ≤ 0.50) ── */
  --border: #c5bfac;
  --icon: #a48e4b;
  /* ── XS tier: emphasis (S ≤ 0.75) ── */
  --accent: #1f7692;
  --accent-secondary: #3ac23a;
  /* ── Typography ── */
  --text-primary: #151513;
  --text-muted: #7e7c74;
  /* ── Semantic (low-sat) ── */
  --semantic-success: #529067;
  --semantic-warning: #8c7443;
  --semantic-error: #a25b54;
  --semantic-info: #507aa4;
}
